from pathlib import Path
import json,hashlib,sys,subprocess
R=Path(__file__).resolve().parents[1];B=R.parents[1];sys.path.insert(0,str(B/'knowledge'));from ink_knowledge import Store
rd=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();v=rd(R/'verification.json');pub=rd(R/'publication.json');obs=rd(R/'observations.json');performance=rd(R/'review/final-performance-review.json');checks={}
old=Store(R/'staging/fair-prior');current=Store(B/'knowledge');oldnames=rd(old.data/'names.json');names=rd(current.data/'names.json')
checks['canonical_exact_published_snapshot']=current.snapshot_id==pub['snapshot']==v['snapshot'] and len(current.members())==2512 and len(names)==4259 and len(oldnames)==4255
checks['canonical_objects_names_preserved']=set(old.members())<=set(current.members()) and all(names.get(n)==h for n,h in oldnames.items()) and set(current.members())-set(old.members())==set(pub['fresh_entries']) and len(pub['fresh_entries'])==4 and not pub['shared_old_entries']
prior=rd(R/'prior-observation-bindings.json');checks['observation_count_and_bytes']=len(list((B/'knowledge/store/observations').glob('*.json')))==25100 and obs['added']==840 and obs['prior_count']==24260 and all(sha(B/'knowledge/store/observations'/f)==h for f,h in prior['files'].items())
checks['verification_receipt_bindings']=all(sha(R/f)==v[k]for f,k in [('review/final-performance-review.json','performance_review_sha256'),('analysis.json','analysis_sha256'),('publication.json','publication_sha256'),('observations.json','observations_sha256')])
base=rd(R/'production-baseline.json');checks['production122_unchanged']=len(base['source_bindings'])==122 and all(sha(B/f)==h for f,h in base['source_bindings'].items()) and sha(Path(base['compiler']))==v['compiler_sha256']
head=subprocess.check_output(['git','-C',str(B/'knowledge'),'rev-parse','HEAD'],text=True).strip();branch=subprocess.check_output(['git','-C',str(B/'knowledge'),'branch','--show-current'],text=True).strip();report=(R/'REPORT.md').read_text();html=(R/'report.html').read_text()
checks['knowledge_main_and_exact_doc_pin']=branch=='main'and head=='03fe0b9bc13fe7e5997157fa1b8c239071f245c0'and head in report
checks['proof_scope_counts']=all(t in report for t in ['zero new generic mathematical laws','13 objects','seven-object closure','four new certificates','All 2,508 previous entries and 4,255 discovery names'])
checks['prior_concat_and_physical_routes']=all(t in report for t in ['prior already applies the old ordered concat-fold law','Literal concat also has four stages','plain 2→1, nested 3→1, filtered 3→1, concat 4→2'])
checks['scalar_control_and_gpu_claims']=all(t in report for t in ['without result allocation/readback','5,472 actual device calls','648 rows','All 6 classified','19 [point losses]','All 48 GPU-versus-CPU cells favor CPU'])and performance['actual_timed_gpu']['calls']==5472
checks['all_documented_aggregates_match']=all(f"{a['geomean']:.3f}× | {a['wins']} / {a['losses']} / {a['inconclusive']}"in report for a in performance['prior_aggregates']+performance['strong_expert_aggregates'])
checks['readme_scope_and_limits']=all(t in(B/'README.md').read_text()for t in ['six cells regress','Rust controls remain faster overall','All 7,560 samples and adverse results are retained'])and all(t in(B/'knowledge/README.md').read_text()for t in ['2,512 entries, 4,259 discovery names and 25,100','no new generic law is duplicated','GPU profitability is mixed'])
checks['post_publication_five_tests']= '\nRan 5 tests in 'in(R/'post-publication-tests.log').read_text() and '\nOK\n'in(R/'post-publication-tests.log').read_text()
checks['rendered_artifacts_present']=len(html)>1000 and (R/'report.jpg').stat().st_size>10000
assert all(checks.values()),{k:v for k,v in checks.items()if not v}
index=subprocess.check_output(['git','-C',str(B),'ls-files','--stage','knowledge'],text=True).strip();out={'status':'passed','checks':checks,'canonical_counts':{'entries':2512,'names':4259,'observations':25100,'new_source_certificates':4,'new_generic':0,'new_observation_groups':840},'knowledge_main_head':head,'distribution_index_at_review':index,'pending_parent_integration':'Parent must stage/commit/push the distribution gitlink to the reviewed knowledge HEAD before claiming complete distribution integration. Current index still carries old pin at review time. Knowledge push confirmation is parent-owned.','limits':'Factual document and canonical review only; no timings, canonical edits or git mutations. Six GPU losses and strong-control limits retained.','bindings':{str(p.relative_to(B)):sha(p)for p in [R/'REPORT.md',R/'report.html',R/'report.jpg',R/'verification.json',R/'publication.json',R/'observations.json',R/'review/final-performance-review.json',B/'README.md',B/'knowledge/README.md',Path(__file__)]}};(R/'review/final-delivery-review.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'status':'passed','knowledge_head':head,'pending_gitlink':index,'checks':checks}))
